package com.create.nautilus.client.menu;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class BallastTankControllerScreen extends AbstractContainerScreen<BallastTankControllerMenu>{public BallastTankControllerScreen(BallastTankControllerMenu m,Inventory i,Component c){super(m,i,c);imageHeight=120;}protected void init(){super.init();for(int id=0;id<4;id++){final int button=id;addRenderableWidget(Button.builder(Component.literal(id%2==0?"-":"+"),b->minecraft.gameMode.handleInventoryButtonClick(menu.containerId,button)).bounds(leftPos+80+(id%2)*24,topPos+28+(id/2)*30,20,20).build());}}protected void renderBg(GuiGraphics g,float p,int x,int y){g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xff26343a);}protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,8,8,0xffffff,false);g.drawString(font,"Fore: "+menu.fore()+"%",8,34,0x66ddff,false);g.drawString(font,"Aft: "+menu.aft()+"%",8,64,0x66ddff,false);}public void render(GuiGraphics g,int x,int y,float p){renderBackground(g,x,y,p);super.render(g,x,y,p);renderTooltip(g,x,y);}}
